-- =============================================================================
-- University of Nigeria, Nsukka -- Faculty of Engineering
-- Department of Electronic Engineering
-- Five-Year Standard Undergraduate B.Eng Degree Programme
-- =============================================================================
-- Transcribed from Chapter Seven (book pages 129-135) of the Faculty of Engineering handbook.
-- 94 rows covering the full programme.
--
-- VERIFICATION: the handbook prints a "Total Credit Hours" for every semester.
-- Each semester's unit values were re-summed and compared against the printed
-- figure -- 20, 17, 19, 18, 22, 21, 22, 15, 16, 19 -- and every one of those reconciles.
-- That check is what makes the units column trustworthy: this handbook
-- right-aligns units, so a value can sit visually against the wrong row, and
-- the printed totals are what pin them back down. Where a semester offers an
-- elective group, only the units a student actually takes are counted toward
-- the total, matching how the handbook totals it.
--
-- DESCRIPTIONS: shared ancillary courses reuse the description already held
-- for that same course code elsewhere in this app, rather than getting freshly
-- invented prose -- a shared course must read identically across every
-- department that lists it. Department-specific courses carry an empty
-- description here: their text lives in the handbook's separate detailed
-- course-description section and is a follow-up pass rather than a guess.
--
-- DEPARTMENT NAME: this handbook chapter's own heading reads "DEPARTMENT OF
-- ELECTRONIC ENGINEERING" (Chapter Seven), matching the ECE course-code
-- prefix used throughout. The current UNN Faculty of Engineering website
-- lists this department as "Electronic and Computer Engineering"; the name
-- stored here follows the handbook chapter itself, consistent with how every
-- other department in this handbook is named after its own chapter heading.
--
-- MTH 121 IS PAIRED WITH "ELEMENTARY MATHEMATICS III" IN FIRST SEMESTER: every
-- other chapter in this handbook uses MTH 121 for Elementary Mathematics II
-- and teaches "III" the following semester (as MTH 122 or MTH 113). This
-- chapter's own First Year table prints MTH 121 = "Elementary Mathematics
-- III" in semester one and MTH 112 = "Elementary Mathematics II" in semester
-- two -- Math III taught before Math II by the chapter's own sequencing.
-- Re-verified directly against the page image at 300dpi; recorded exactly as
-- printed rather than reordered to match the other chapters' convention.
--
-- PHY 107 = 2 UNITS HERE, NOT 3: Civil and Electrical Engineering's chapters
-- both print PHY 107 "Fundamentals of Physics I" as 3 units; this chapter
-- prints it as 2, and the semester's own printed total of 20 only reconciles
-- with 2. Recorded as printed -- a genuine cross-chapter inconsistency, not
-- a transcription error.
--
-- EEE 361's UNIT VALUE IS PHYSICALLY SMUDGED IN THE SOURCE PHOTOGRAPH: at
-- 300 Level first semester, an ink mark obscures the printed digit next to
-- "EEE 361 -- Electrical Machines I". It is stored here as 3 units, the only
-- value consistent with the semester's printed total of 22 (12 units from the
-- five ECE majors + 1 for EEE 351 + 2 for STA 203 + 2 for ECE 371 + 2 for
-- CED 341 leaves exactly 3 for EEE 361), and matching the unit value this
-- same course carries in the Civil and Electrical Engineering chapters.
--
-- FIFTH-YEAR ELECTIVES: second semester's own footnote reads "Two courses
-- from any area(s) of specialization (Communications, Control, Digital and
-- Computer, Opto-electronics, Instrumentation) may be chosen from the
-- elective courses" and the handbook folds that straight into a flat
-- "Electives -- 6" line in its own total (5 majors = 13, + 6 = 19). All
-- elective options legible in the source are stored as is_elective = true;
-- the Instrumentation group's list was cut off after its first entry
-- (ECE 562) by the edge of the photographed page, so only that one option is
-- recorded for that group -- nothing was extrapolated to fill the gap.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Electronic Engineering';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name, is_elective)
values
  ('EGR 101', 'Introduction to Engineering', 'University of Nigeria, Nsukka', 'Faculty of Engineering', 'Electronic Engineering', '100 Level', 'first', 2, 'An overview of engineering as a profession. Historical perspective, Discipline, Rationalization, professional affiliations, professional journey, successful studentship, creativity, roles of science and Technology; Engineering and Society: The role of engineers in nation building, professional impacts of Engineering practice and mitigation measures, professional challenges in Nigeria, historical and professional roles; Basic information on Agricultural and Bioresources Engineering, Professional practice, Sustainable Agricultural production in Nigeria; Introduction to Biomedical Engineering, Scope of biomedical engineering practice: A science perspective of Civil Engineering, corporate personality of Civil Engineering; Civil Engineering professional practice; Basic information on Electrical Engineering, Scope of Electrical Engineering professional practice; Electric power generation in Nigeria; Evolution to Electronic Engineering, Scope of Electronic Engineering Professional practice, practice of Electronic Engineering in Nigeria; Basic information on Mechanical Engineering, Scope of Mechanical Engineering professional practice, practice of Mechanical Engineering in Nigeria; Introduction to Mechatronics Engineering, Scope of Mechatronics engineering practice; Basic information on Metallurgical and Materials Engineering, Scope of Metallurgical and Materials Engineering professional practice, practice of Metallurgical and Materials Engineering.', '["An overview of engineering as a profession. Historical perspective, Discipline, Rationalization, professional affiliations, professional journey, successful studentship, creativity, roles of science and Technology", "Engineering and Society: The role of engineers in nation building, professional impacts of Engineering practice and mitigation measures, professional challenges in Nigeria", "Basic information on Agricultural and Bioresources Engineering; Introduction to Biomedical Engineering", "A science perspective of Civil Engineering, corporate personality and professional practice of Civil Engineering", "Basic information on Electrical Engineering; Electric power generation in Nigeria; Evolution to Electronic Engineering", "Basic information on Mechanical Engineering, Scope and practice of Mechanical Engineering in Nigeria", "Introduction to Mechatronics Engineering; Basic information on Metallurgical and Materials Engineering"]'::jsonb, 'Faculty of Engineering handbook', false),
  ('MTH 111', 'Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Engineering', 'Electronic Engineering', '100 Level', 'first', 3, 'Elementary set theory, subsets, union, intersection, complements. Venn diagrams, real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem. Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae. Complex numbers, algebra of complex numbers, the Argand diagram, De Moivre''s theorem, nth roots of unity.', '["Elementary set theory, subsets, union, intersection, complements", "Venn diagrams, real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem", "Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae", "Complex numbers, algebra of complex numbers, the Argand diagram, De Moivre''s theorem, nth roots of unity"]'::jsonb, 'Faculty of Engineering handbook', false),
  ('MTH 121', 'Elementary Mathematics III', 'University of Nigeria, Nsukka', 'Faculty of Engineering', 'Electronic Engineering', '100 Level', 'first', 3, 'Functions of a real variable, graphs, limits and continuity. The derivative as limit of rate of change. Techniques of differentiation. Curve sketching, integration as an inverse of differentiation. Methods of integration, definite integrals. Application of integration to areas and volumes.', '["Functions of a real variable, graphs, limits and continuity", "The derivative as limit of rate of change", "Techniques of differentiation", "Curve sketching, integration as an inverse of differentiation", "Methods of integration, definite integrals", "Application of integration to areas and volumes"]'::jsonb, 'Faculty of Engineering handbook', false),
  ('CHM 101', 'Basic Principles of Chemistry I', 'University of Nigeria, Nsukka', 'Faculty of Engineering', 'Electronic Engineering', '100 Level', 'first', 2, 'Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories. Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position. Nuclear Chemistry: Radioactivity and its practical applications.', '["Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories", "Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position", "Nuclear Chemistry: Radioactivity and its practical applications"]'::jsonb, 'Faculty of Engineering handbook', false),
  ('CHM 171', 'Basic Practical Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Engineering', 'Electronic Engineering', '100 Level', 'first', 2, 'Laboratory operations: theory and practice of simple volumetric and quantitative analysis, simple organic preparations, functional group reactions, and physical chemistry determinations.', '["Laboratory operations: theory and practice of simple volumetric and quantitative analysis, simple organic preparations, functional group reactions, and physical chemistry determinations"]'::jsonb, 'Faculty of Engineering handbook', false),
