  ('GSP 101', 'The Use of English I', 'University of Nigeria, Nsukka', 'Faculty of Engineering', 'Electronic Engineering', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Engineering handbook', false),
